function currentLayout(){return galleryDefinition().layout||(currentStyle()==='modern'?'terraced':'ring');}
function isTerraced(){return currentLayout()==='terraced';}
const layoutBuilders={ring:{architecture:buildClassicArchitecture,artwork:buildClassicArtwork},terraced:{architecture:buildTerracedArchitecture,artwork:buildTerracedArtwork},courtyard:{architecture:buildCourtyardArchitecture,artwork:buildCourtyardArtwork}};
