function buildArtwork(m,i){layoutBuilders[currentLayout()].artwork(m,i);}
function floorLevel(y=eye.y){return y>=4?1:0;}
function terraceSupport(x,z,level=floorLevel()){if(level===0)return Math.abs(x)<=35&&Math.abs(z)<=33;return terracePlatforms.some(p=>x>=p.x1&&x<=p.x2&&z>=p.z1&&z<=p.z2);}
function terraceWalkable(x,z,y=eye.y){const level=floorLevel(y);return [[-.3,-.3],[.3,-.3],[-.3,.3],[.3,.3]].every(([dx,dz])=>terraceSupport(x+dx,z+dz,level));}
