 for(let zone=0;zone<zoneCount;zone++){const z=courtZ(zone);ctx.fillStyle=zone===getZone()?'#ba9b6a88':'#243d2e99';ctx.fillRect(-12*scale,(z-10.8)*scale,24*scale,21.6*scale);ctx.fillStyle='#e3d8b9';ctx.font='17px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(`${String(zoneNumber(zone)).padStart(2,'0')} 院`,0,z*scale);ctx.font='11px sans-serif';ctx.fillText(`${zoneItems(zone).length} 幅`,0,(z+3.8)*scale);}
