function optimizeStaticArchitecture(){
 world.updateMatrixWorld(true);const groups=new Map(),shared=new Set(Object.values(mats));world.traverse(o=>{if(!o.isMesh||!shared.has(o.material)||(o.geometry.type==='ExtrudeGeometry'||o.userData.hideInOverview))return;let p=o.parent;while(p){if(p===globe)return;p=p.parent;}const list=groups.get(o.material)||[];list.push(o);groups.set(o.material,list);});
 for(const [mat,objects] of groups){if(objects.length<4)continue;const chunks=[],lengths={position:0,normal:0,uv:0};for(const mesh of objects){const g=(mesh.geometry.index?mesh.geometry.toNonIndexed():mesh.geometry.clone()).applyMatrix4(mesh.matrixWorld);chunks.push(g);for(const name of Object.keys(lengths))lengths[name]+=g.getAttribute(name)?.array.length||0;}const merged=new THREE.BufferGeometry();for(const [name,length] of Object.entries(lengths)){if(!length)continue;const data=new Float32Array(length);let offset=0;for(const g of chunks){const attr=g.getAttribute(name);if(attr){data.set(attr.array,offset);offset+=attr.array.length;}}merged.setAttribute(name,new THREE.BufferAttribute(data,name==='uv'?2:3));}merged.computeBoundingSphere();const batch=new THREE.Mesh(merged,mat);batch.castShadow=true;batch.receiveShadow=true;world.add(batch);for(const obj of objects){obj.removeFromParent();obj.geometry.dispose();}for(const g of chunks)g.dispose();}
}
