 const centerLight=new THREE.PointLight('#edc581',60,24,2);centerLight.position.set(0,6,0);scene.add(centerLight);lights.push(centerLight);
 for(let i=0;i<zoneCount;i++){const a=i*TAU/zoneCount,l=new THREE.PointLight('#ffdfaa',38,28,2);l.position.set(34*Math.sin(a),5.9,34*Math.cos(a));scene.add(l);lights.push(l);const fixture=new THREE.Mesh(new THREE.TorusGeometry(isTerraced()?1.05:1.5,.045,8,48),new THREE.MeshBasicMaterial({color:isTerraced()?'#a0e8f5':'#ffe6ad'}));fixture.position.copy(l.position);fixture.rotation.x=Math.PI/2;world.add(fixture);}
